window.LANGUAGE_FOCUS = {"version":1,"origin":"本站原创主题配套短语与句型，非教材原文摘录。","units":[{"unitId":"7a-u1","phrases":[{"phrase":"introduce oneself","meaning":"介绍自己","example":"I introduce myself to my new classmates.","translation":"我向新同学介绍自己。"},{"phrase":"be in Class Three","meaning":"在三班","example":"Lily and Max are in Class Three.","translation":"莉莉和马克斯在三班。"},{"phrase":"be interested in","meaning":"对……感兴趣","example":"I am interested in stories about school life.","translation":"我对校园生活故事感兴趣。"},{"phrase":"make friends with","meaning":"与……交朋友","example":"I hope to make friends with other readers.","translation":"我希望与其他爱读书的人交朋友。"}],"patterns":[{"pattern":"I am + 名词 / 形容词.","meaning":"介绍身份或描述自己","example":"I am a new student, and I am a little quiet.","translation":"我是一名新生，而且我有一点文静。","tip":"I 与 am 搭配；单数可数名词 student 前需要冠词 a。"},{"pattern":"My favourite ... is ...","meaning":"介绍自己最喜欢的事物","example":"My favourite place is the reading corner.","translation":"我最喜欢的地方是阅读角。","tip":"主语 My favourite place 是单数，be 动词用 is。"},{"pattern":"Are you ...? — Yes, I am. / No, I am not.","meaning":"询问对方的身份或状态并回答","example":"Are you ready for the first lesson? Yes, I am.","translation":"你准备好上第一节课了吗？是的，我准备好了。","tip":"问句中将 are 放到 you 前；回答时根据 I 改用 am。"}]},{"unitId":"7a-u2","phrases":[{"phrase":"enjoy doing something","meaning":"喜欢做某事","example":"Eva enjoys drawing buildings after school.","translation":"伊娃喜欢放学后画建筑。"},{"phrase":"take photos","meaning":"拍照","example":"My sister takes photos of old bridges.","translation":"我姐姐拍摄老桥的照片。"},{"phrase":"on one's way home","meaning":"在某人回家的路上","example":"I draw a small shop on my way home.","translation":"我在回家的路上画一家小店。"},{"phrase":"start with","meaning":"从……开始","example":"We start with a picture of one window.","translation":"我们从画一扇窗开始。"}],"patterns":[{"pattern":"Do you + 动词原形 ...?","meaning":"询问爱好或日常习惯","example":"Do you draw in your notebook every day?","translation":"你每天都在笔记本上画画吗？","tip":"一般现在时中，主语是 you，问句用 Do，后面的动词保持原形。"},{"pattern":"He / She + 动词第三人称单数 ...","meaning":"描述他人的习惯","example":"She practises drawing for ten minutes each evening.","translation":"她每天晚上练习画画十分钟。","tip":"主语是 she，一般现在时中 practise 变为 practises。"},{"pattern":"... does not + 动词原形 ...","meaning":"表达第三人称单数的否定","example":"My brother does not copy other people's pictures.","translation":"我弟弟不临摹别人的画。","tip":"does not 后用动词原形 copy，不再加 s。"}]},{"unitId":"7a-u3","phrases":[{"phrase":"show somebody around","meaning":"带某人参观","example":"Alex shows the visitor around the library.","translation":"亚历克斯带访客参观图书馆。"},{"phrase":"borrow ... from ...","meaning":"从……借入……","example":"We borrow storybooks from the school library.","translation":"我们从学校图书馆借故事书。"},{"phrase":"next to","meaning":"紧邻；在……旁边","example":"The reading area is next to the hall.","translation":"阅读区紧邻礼堂。"},{"phrase":"look after","meaning":"照料；照看","example":"Students look after the plants in the garden.","translation":"学生们照料花园里的植物。"}],"patterns":[{"pattern":"It is + 地点描述.","meaning":"用 it 接续介绍一个地点","example":"This is our library. It is beside the hall.","translation":"这是我们的图书馆。它在礼堂旁边。","tip":"it 可以指代前句提到的单数事物，避免重复 library。"},{"pattern":"... help / like / know + 宾格代词.","meaning":"用宾格代词指代人物","example":"Those students need help, and I can help them.","translation":"那些学生需要帮助，我可以帮他们。","tip":"动词 help 后用宾格 them；句首作主语时用 they。"},{"pattern":"Would you like to + 动词原形 ...?","meaning":"礼貌邀请对方做某事","example":"Would you like to visit our reading area first?","translation":"您想先参观我们的阅读区吗？","tip":"would like 后接 to do；此处是邀请，不是询问日常习惯。"}]},{"unitId":"7a-u4","phrases":[{"phrase":"put away","meaning":"把……收好","example":"I put away my books before dinner.","translation":"我晚饭前把书收好。"},{"phrase":"after class","meaning":"下课后","example":"Sam sometimes helps his teacher after class.","translation":"萨姆有时下课后帮助老师。"},{"phrase":"get ready for","meaning":"为……做好准备","example":"We get ready for the club at lunch.","translation":"我们午饭时为社团活动做好准备。"},{"phrase":"on time","meaning":"准时","example":"I check my timetable so I can arrive on time.","translation":"我查看时间表，以便准时到达。"}],"patterns":[{"pattern":"... at + 钟点 / on + 星期.","meaning":"说明活动的具体时间","example":"Our reading club starts at four twenty on Thursday.","translation":"我们的阅读社团周四四点二十分开始活动。","tip":"钟点前用 at；具体星期前用 on。"},{"pattern":"主语 + usually / sometimes + 实义动词 ...","meaning":"说明日常活动的频率","example":"I usually do my homework before dinner.","translation":"我通常在晚饭前做作业。","tip":"频度副词通常放在实义动词前；在 be 动词后。"},{"pattern":"How often do you ...?","meaning":"询问活动频率","example":"How often do you read before breakfast?","translation":"你多久在早餐前读一次书？","tip":"How often 问频率；可用 every day、twice a week 等回答。"}]},{"unitId":"7a-u5","phrases":[{"phrase":"a bowl of","meaning":"一碗……","example":"I have a bowl of rice for lunch.","translation":"我午饭吃一碗米饭。"},{"phrase":"a glass of","meaning":"一玻璃杯……","example":"There is a glass of milk beside my plate.","translation":"我的盘子旁有一玻璃杯牛奶。"},{"phrase":"half a banana","meaning":"半根香蕉","example":"Each fruit cup has half a banana.","translation":"每个水果杯里有半根香蕉。"},{"phrase":"go for a walk","meaning":"去散步","example":"We go for a walk after the evening meal.","translation":"我们晚饭后去散步。"}],"patterns":[{"pattern":"How many + 可数名词复数 ...?","meaning":"询问可数物品的数量","example":"How many apples do we need for six cups?","translation":"做六杯水果杯，我们需要多少个苹果？","tip":"many 后接可数名词复数，如 apples。"},{"pattern":"How much + 不可数名词 ...?","meaning":"询问不可数物品的量","example":"How much yoghurt is there in the fridge?","translation":"冰箱里有多少酸奶？","tip":"yoghurt 在这里作不可数名词；询问量时用 How much。"},{"pattern":"There is some + 不可数名词 ...","meaning":"说明有一些某物","example":"There is some bread on the breakfast table.","translation":"早餐桌上有一些面包。","tip":"bread 不可数，不能直接加 s；There is 与它搭配。"}]},{"unitId":"7a-u6","phrases":[{"phrase":"look good in","meaning":"穿……好看","example":"You look good in the blue jacket.","translation":"你穿这件蓝色夹克很好看。"},{"phrase":"go well with","meaning":"与……很相配","example":"The yellow hat goes well with my coat.","translation":"这顶黄色帽子与我的外套很相配。"},{"phrase":"choose ... for ...","meaning":"为……选择……","example":"I choose comfortable shoes for the park visit.","translation":"我为这次公园参观选择舒适的鞋。"},{"phrase":"be made of","meaning":"由……制成（可辨认原材料）","example":"This scarf is made of soft cloth.","translation":"这条围巾由柔软的布料制成。"}],"patterns":[{"pattern":"Which ... do you prefer, A or B?","meaning":"在两个选项中询问偏好","example":"Which jacket do you prefer, the blue one or the red one?","translation":"你更喜欢哪件夹克，蓝色的还是红色的？","tip":"Which 用于有一定范围的选择；回答应明确选项。"},{"pattern":"Why ...? — Because ...","meaning":"询问并说明选择理由","example":"Why do you like this coat? Because it has useful pockets.","translation":"你为什么喜欢这件外套？因为它有实用的口袋。","tip":"Why 问原因，because 引导说明原因的句子。"},{"pattern":"Is ... A or B?","meaning":"询问两个备选情况","example":"Is tomorrow's class talk indoors or outdoors?","translation":"明天的班级发言活动在室内还是室外？","tip":"这是选择疑问句，通常用具体选项回答，不只答 yes 或 no。"}]},{"unitId":"7a-u7","phrases":[{"phrase":"pocket money","meaning":"零花钱","example":"I keep my pocket money in a small box.","translation":"我把零花钱放在一个小盒子里。"},{"phrase":"save up for","meaning":"为……攒钱","example":"We save up for a new class dictionary.","translation":"我们为一本新的班级词典攒钱。"},{"phrase":"check the price","meaning":"核对价格","example":"Please check the price before you pay.","translation":"付款前请核对价格。"},{"phrase":"spend ... on ...","meaning":"在……上花费……","example":"I spend ten yuan on a notebook.","translation":"我花十元钱买了一个笔记本。"}],"patterns":[{"pattern":"There are some + 可数名词复数 ...","meaning":"说明现有的一些物品","example":"There are some unused pencils in our classroom.","translation":"我们教室里有一些未使用的铅笔。","tip":"先用 there are 清点已有物品；复数名词前可以用 some。"},{"pattern":"There is not any + 不可数名词 ...","meaning":"说明没有某物","example":"There is not any money left for another poster.","translation":"已经没有钱再买一张海报了。","tip":"否定句中常用 any；money 不可数，be 动词用 is。"},{"pattern":"Are there any ...?","meaning":"询问是否还有某物","example":"Are there any cheaper notebooks in this shop?","translation":"这家店里有更便宜的笔记本吗？","tip":"一般疑问句常用 any；notebooks 是复数，开头用 Are there。"}]},{"unitId":"7a-u8","phrases":[{"phrase":"put up decorations","meaning":"挂起装饰物","example":"They are putting up decorations near the door.","translation":"他们正在门边挂装饰物。"},{"phrase":"take part in","meaning":"参加","example":"Everyone can take part in the class celebration.","translation":"每个人都可以参加班级庆祝活动。"},{"phrase":"wait for","meaning":"等候","example":"We are waiting for our guests by the gate.","translation":"我们正在大门旁等候客人。"},{"phrase":"have fun","meaning":"玩得开心","example":"The children are having fun at the party.","translation":"孩子们在聚会上玩得很开心。"}],"patterns":[{"pattern":"主语 + am / is / are + 动词-ing ...","meaning":"描述此刻正在发生的活动","example":"We are preparing a quiet reading corner for the party.","translation":"我们正在为聚会布置一个安静的阅读角。","tip":"现在进行时需要 be 动词和 -ing 形式两个部分。"},{"pattern":"Is / Are + 主语 + 动词-ing ...?","meaning":"询问正在进行的活动","example":"Are the students making cards for their guests?","translation":"学生们正在给客人制作卡片吗？","tip":"把 be 动词提到主语前；make 的 -ing 形式是 making。"},{"pattern":"What + am / is / are + 主语 + doing?","meaning":"询问某人此刻在做什么","example":"What is Amy doing beside the welcome desk?","translation":"埃米正在接待台旁做什么？","tip":"特殊疑问词后保留一般疑问句语序：is Amy doing。"}]},{"unitId":"7b-u1","phrases":[{"phrase":"on the second floor","meaning":"在二楼","example":"Our flat is on the second floor.","translation":"我们的公寓在二楼。"},{"phrase":"share a room with","meaning":"与……共用一个房间","example":"I share a room with my younger brother.","translation":"我和弟弟共用一个房间。"},{"phrase":"in front of","meaning":"在……前面","example":"A small garden is in front of our building.","translation":"我们楼前有一个小花园。"},{"phrase":"welcome to","meaning":"欢迎来到……","example":"Welcome to our new home near the park.","translation":"欢迎来到我们在公园附近的新家。"}],"patterns":[{"pattern":"... live / lives at + 地址.","meaning":"说明居住地址","example":"We live at 18 Garden Road.","translation":"我们住在花园路十八号。","tip":"门牌号用基数词；此例为练习用虚构地址。"},{"pattern":"... is on the + 序数词 + floor.","meaning":"说明所在楼层","example":"My room is on the third floor.","translation":"我的房间在三楼。","tip":"楼层前用 on；序数词 third 前通常有 the。"},{"pattern":"There are + 数字 + 可数名词复数 ...","meaning":"用数量介绍房间或设施","example":"There are two bedrooms in our flat.","translation":"我们的公寓里有两间卧室。","tip":"数字大于一时，名词 bedroom 用复数 bedrooms。"}]},{"unitId":"7b-u2","phrases":[{"phrase":"give somebody a hand","meaning":"帮某人一把","example":"I will give our new neighbour a hand.","translation":"我会帮我们的新邻居一把。"},{"phrase":"help ... with ...","meaning":"在……方面帮助……","example":"We are going to help visitors with their questions.","translation":"我们打算帮助访客解答问题。"},{"phrase":"plan to do something","meaning":"计划做某事","example":"Our group plans to paint a welcome sign.","translation":"我们小组计划画一块欢迎标牌。"},{"phrase":"at the community centre","meaning":"在社区中心","example":"The meeting will be at the community centre.","translation":"会议将在社区中心举行。"}],"patterns":[{"pattern":"主语 + will + 动词原形 ...","meaning":"表达临时决定或愿意承担的任务","example":"I will carry the maps to the welcome desk.","translation":"我来把地图搬到接待台。","tip":"will 后接动词原形；可用于当场作出的决定。"},{"pattern":"主语 + am / is / are going to + 动词原形 ...","meaning":"说明已有的打算","example":"We are going to make a guide for new neighbours.","translation":"我们打算为新邻居制作一份指南。","tip":"be going to 表达事先的计划；be 随主语变化。"},{"pattern":"Shall we + 动词原形 ...?","meaning":"提议一起做某事","example":"Shall we ask the neighbours what they need?","translation":"我们问问邻居需要什么，好吗？","tip":"Shall we 常用于提出共同活动的建议。"}]},{"unitId":"7b-u3","phrases":[{"phrase":"walk along","meaning":"沿着……走","example":"Walk along River Street to the bridge.","translation":"沿着河滨街走到桥边。"},{"phrase":"on one's left","meaning":"在某人的左边","example":"The bookshop is on your left.","translation":"书店在你的左边。"},{"phrase":"turn right at","meaning":"在……向右转","example":"Turn right at the first crossing.","translation":"在第一个十字路口向右转。"},{"phrase":"be famous for","meaning":"因……而闻名","example":"Our town is famous for its old stone bridge.","translation":"我们的小镇因古老的石桥而闻名。"}],"patterns":[{"pattern":"There is a / an ... near ...","meaning":"首次介绍附近的一处地点","example":"There is a small museum near the river.","translation":"河边附近有一座小博物馆。","tip":"首次提到单数可数名词常用 a / an；再次提及时可用 the。"},{"pattern":"... is between ... and ...","meaning":"说明某地位于两处之间","example":"The garden is between the library and the bakery.","translation":"花园在图书馆和面包店之间。","tip":"between ... and ... 中两处地点要表达完整。"},{"pattern":"The ... is behind / opposite / beside ...","meaning":"用方位词给出清楚的位置","example":"The bus stop is opposite the town hall.","translation":"公交站在市政厅对面。","tip":"opposite 表示正对面，behind 表示在后面，beside 表示在旁边。"}]},{"unitId":"7b-u4","phrases":[{"phrase":"paper cutting","meaning":"剪纸","example":"My grandmother teaches paper cutting at the centre.","translation":"我奶奶在中心教剪纸。"},{"phrase":"learn from","meaning":"向……学习","example":"We learn from a local craft artist.","translation":"我们向一位本地工艺师学习。"},{"phrase":"belong to","meaning":"属于","example":"This red paper fish belongs to Lin.","translation":"这条红色纸鱼属于琳。"},{"phrase":"by hand","meaning":"用手工","example":"The artist makes each small flower by hand.","translation":"这位艺术家用手工制作每一朵小花。"}],"patterns":[{"pattern":"Whose ... is this? — It is ...'s.","meaning":"询问并说明物品所属","example":"Whose paper bird is this? It is Amy's.","translation":"这只纸鸟是谁的？是埃米的。","tip":"Whose 问所属；人名后加 's 表示某人的。"},{"pattern":"This is my ...; that one is yours.","meaning":"区分形容词性和名词性物主代词","example":"This is my drawing; that one is yours.","translation":"这是我的画，那幅是你的。","tip":"my 后要接名词；yours 可单独使用，不能再加 drawing。"},{"pattern":"These ... are ...'s.","meaning":"说明复数物品所属","example":"These two paper flowers are the artist's.","translation":"这两朵纸花是那位艺术家的。","tip":"物品为复数时用 are；单数所有者 artist 后加 's。"}]},{"unitId":"7b-u5","phrases":[{"phrase":"be friendly to","meaning":"对……友好","example":"The dog is friendly to familiar visitors.","translation":"这只狗对熟悉的访客很友好。"},{"phrase":"take care of","meaning":"照顾","example":"We take care of the rabbit after school.","translation":"我们放学后照顾这只兔子。"},{"phrase":"ask for permission","meaning":"请求允许","example":"Please ask for permission before touching the animal.","translation":"触摸动物前请先征得允许。"},{"phrase":"keep ... clean","meaning":"使……保持干净","example":"The staff keep the animal's sleeping area clean.","translation":"工作人员使动物的睡眠区域保持干净。"}],"patterns":[{"pattern":"主语 + can + 动词原形 ...","meaning":"说明动物的能力","example":"This clever dog can find its blue toy.","translation":"这只聪明的狗能找到它的蓝色玩具。","tip":"can 后接动词原形；不能因主语是 dog 而加 s。"},{"pattern":"May I + 动词原形 ...?","meaning":"礼貌请求允许","example":"May I watch the rabbit from here?","translation":"我可以从这里观察这只兔子吗？","tip":"May I 常用于较礼貌地请求允许；先听取工作人员答复。"},{"pattern":"主语 + looks / is + 形容词.","meaning":"描述外表或状态","example":"The small cat looks calm beside its owner.","translation":"这只小猫在主人身边显得很平静。","tip":"look 作连系动词时，后接形容词 calm，而不是副词。"}]},{"unitId":"7b-u6","phrases":[{"phrase":"at the foot of","meaning":"在……脚下","example":"There is a quiet village at the foot of the hill.","translation":"山脚下有一个安静的村庄。"},{"phrase":"in the distance","meaning":"在远处","example":"We can see a small bridge in the distance.","translation":"我们能看见远处的一座小桥。"},{"phrase":"take a closer look","meaning":"更仔细地看一看","example":"I stop to take a closer look at a leaf.","translation":"我停下来更仔细地看一片叶子。"},{"phrase":"a patch of","meaning":"一小片……","example":"A patch of sunlight falls on the lake.","translation":"一小片阳光洒在湖面上。"}],"patterns":[{"pattern":"What a / an + 形容词 + 单数可数名词!","meaning":"用感叹句赞叹一处景物","example":"What a beautiful view from this little bridge!","translation":"从这座小桥上看，景色真美啊！","tip":"单数可数名词 view 前需要 a；beautiful 以辅音音素开头。"},{"pattern":"How + 形容词 + 主语 + 谓语!","meaning":"强调景物的某种特点","example":"How clear the water is today!","translation":"今天的水多么清澈啊！","tip":"How 后直接接形容词 clear，后面是陈述语序。"},{"pattern":"There is something + 形容词 ...","meaning":"描述某种特别的发现","example":"There is something unusual under that large leaf.","translation":"那片大叶子下面有点不寻常的东西。","tip":"形容词 unusual 放在不定代词 something 后。"}]},{"unitId":"7b-u7","phrases":[{"phrase":"set off","meaning":"出发","example":"We set off for the park at eight yesterday.","translation":"我们昨天八点出发去公园。"},{"phrase":"put up a tent","meaning":"搭帐篷","example":"Our teacher helped us put up a tent.","translation":"老师帮助我们搭起了帐篷。"},{"phrase":"take turns","meaning":"轮流","example":"We took turns carrying the sketching materials.","translation":"我们轮流搬运写生材料。"},{"phrase":"on the way back","meaning":"在返回的路上","example":"On the way back, we talked about our sketches.","translation":"在返回的路上，我们谈论了各自的速写。"}],"patterns":[{"pattern":"主语 + 动词过去式 ... yesterday.","meaning":"叙述已经完成的户外活动","example":"We walked beside the lake yesterday morning.","translation":"我们昨天上午沿着湖边散步。","tip":"有明确过去时间时用一般过去时；walk 的过去式是 walked。"},{"pattern":"Did + 主语 + 动词原形 ...?","meaning":"询问过去的经历","example":"Did you notice the small birds near the bridge?","translation":"你注意到桥附近的小鸟了吗？","tip":"Did 后的动词用原形 notice，不用 noticed。"},{"pattern":"主语 + did not + 动词原形 ...","meaning":"说明过去没有做的事","example":"We did not leave any rubbish in the park.","translation":"我们没有把任何垃圾留在公园里。","tip":"一般过去时否定句用 did not，后面用动词原形 leave。"}]},{"unitId":"7b-u8","phrases":[{"phrase":"fall into","meaning":"掉进","example":"A silver key fell into the empty cup.","translation":"一把银色钥匙掉进了空杯子里。"},{"phrase":"look for","meaning":"寻找","example":"The girl looked for a path through the garden.","translation":"女孩寻找一条穿过花园的小路。"},{"phrase":"all of a sudden","meaning":"突然","example":"All of a sudden, the paper boat began to sing.","translation":"突然，纸船开始唱歌。"},{"phrase":"find one's way","meaning":"找到路","example":"The boy found his way home by following the lights.","translation":"男孩跟着灯光找到了回家的路。"}],"patterns":[{"pattern":"One day, ... + 动词过去式 ...","meaning":"交代故事的开端","example":"One day, a boy found a door inside his notebook.","translation":"一天，一个男孩在笔记本里发现了一扇门。","tip":"叙述过去的故事时，同一时间线上的主要动作通常用过去式。"},{"pattern":"... was / were ..., but ...","meaning":"描述过去的状态并形成转折","example":"The bridge was narrow, but it was strong.","translation":"桥很窄，但是很结实。","tip":"一般过去时中，单数主语用 was，复数主语用 were。"},{"pattern":"First ..., then ..., and finally ...","meaning":"按先后顺序讲述故事","example":"First she opened the box, then she read the note, and finally she smiled.","translation":"她先打开盒子，然后读了便条，最后笑了。","tip":"连接词串起动作；opened、read、smiled 都表示过去动作，read 读作 /red/。"}]},{"unitId":"8a-u1","phrases":[{"phrase":"keep a promise","meaning":"遵守诺言","example":"A good friend tries to keep a promise.","translation":"好朋友会努力遵守诺言。"},{"phrase":"tell the truth","meaning":"说实话","example":"Mia tells the truth even when she makes a mistake.","translation":"米娅即使犯了错也说实话。"},{"phrase":"a friend in need","meaning":"处于困难中的朋友","example":"We listen carefully to a friend in need.","translation":"我们认真倾听处于困难中的朋友。"},{"phrase":"trust ... with ...","meaning":"信任……并把……托付给对方","example":"I trust Ben with my favourite sketchbook.","translation":"我信任本，把我最喜欢的速写本交给他保管。"}],"patterns":[{"pattern":"... is + 比较级 + than ...","meaning":"比较两个人的一项特点","example":"Mia is more patient than I am when we work together.","translation":"我们一起做事时，米娅比我更有耐心。","tip":"patient 是多音节形容词，比较级用 more patient。"},{"pattern":"... is the + 最高级 + 范围.","meaning":"说明某人在一个范围内最突出","example":"Ben is the most helpful member of our group.","translation":"本是我们小组里最乐于助人的成员。","tip":"最高级通常有 the，并要给出比较范围，如 of our group。"},{"pattern":"... is as + 形容词原级 + as ...","meaning":"说明两者在某方面相当","example":"My friend is as honest as her older sister.","translation":"我的朋友和她姐姐一样诚实。","tip":"as ... as 之间用原级 honest，不用比较级。"}]},{"unitId":"8a-u2","phrases":[{"phrase":"fewer ... than ...","meaning":"……比……更少（可数数量）","example":"Our library has fewer magazines than theirs.","translation":"我们的图书馆比他们的图书馆杂志更少。"},{"phrase":"more time for","meaning":"有更多时间用于……","example":"A shorter queue gives us more time for reading.","translation":"队伍短一些让我们有更多时间阅读。"},{"phrase":"listen to opinions","meaning":"听取意见","example":"We listen to opinions before changing the timetable.","translation":"我们在更改时间表前听取意见。"},{"phrase":"make a suggestion","meaning":"提出建议","example":"Each student can make a suggestion about the library.","translation":"每个学生都可以就图书馆提出一条建议。"}],"patterns":[{"pattern":"... has more / fewer + 可数名词复数 + than ...","meaning":"比较可数物品数量","example":"The new reading room has more seats than the old one.","translation":"新阅览室的座位比旧阅览室多。","tip":"more 表示更多，fewer 表示更少；后面接可数名词复数。"},{"pattern":"... has less + 不可数名词 + than ...","meaning":"比较不可数事物的量","example":"Our quiet room has less noise than the busy hall.","translation":"我们的安静阅览室比繁忙的礼堂噪声少。","tip":"noise 在这里不可数，用 less，不用 fewer。"},{"pattern":"... is one of the + 最高级 + 可数名词复数.","meaning":"表达属于最……的事物之一","example":"The reading corner is one of the most popular places in our school.","translation":"阅读角是我们学校最受欢迎的地方之一。","tip":"one of 后面的名词用复数 places；整段主语仍是单数。"}]},{"unitId":"8a-u3","phrases":[{"phrase":"learn by oneself","meaning":"自学","example":"I learned the new drawing method by myself.","translation":"我自学了这种新的绘画方法。"},{"phrase":"make mistakes","meaning":"犯错","example":"We make mistakes when we try a new skill.","translation":"我们尝试一项新技能时会犯错。"},{"phrase":"break ... into ...","meaning":"把……分成……","example":"I break the long talk into three short parts.","translation":"我把长篇发言分成三个短部分。"},{"phrase":"make progress","meaning":"取得进步","example":"Regular practice helps me make progress in speaking.","translation":"有规律的练习帮助我在口语方面取得进步。"}],"patterns":[{"pattern":"... does ... more + 副词 + than ...","meaning":"比较做事的方式","example":"I check my notes more carefully than before.","translation":"我比以前更仔细地检查笔记。","tip":"carefully 是多音节副词，比较级用 more carefully。"},{"pattern":"主语 + 动词 + 反身代词 ...","meaning":"表示动作由自己完成或作用于自己","example":"We taught ourselves how to use the recording tool.","translation":"我们自学了如何使用录音工具。","tip":"主语是 we，对应反身代词 ourselves；teach oneself 表示自学。"},{"pattern":"主语 + 动词 + the + 副词最高级 + 比较范围.","meaning":"比较三者或以上做事的表现","example":"Of the three learners, Eva speaks the most clearly.","translation":"三位学习者中，伊娃说得最清楚。","tip":"比较三者或以上可用副词最高级；多音节副词 clearly 用 the most clearly。"}]},{"unitId":"8a-u4","phrases":[{"phrase":"cut out","meaning":"剪出","example":"Cut out four paper leaves for the message board.","translation":"为留言板剪出四片纸叶子。"},{"phrase":"stick ... to ...","meaning":"把……粘到……上","example":"Stick the labels to the empty boxes.","translation":"把标签粘到空盒子上。"},{"phrase":"turn ... into ...","meaning":"把……变成……","example":"We turn an old box into a useful organiser.","translation":"我们把一个旧盒子变成实用的收纳盒。"},{"phrase":"try out","meaning":"试用；试验","example":"We try out the paper stand before decorating it.","translation":"我们先试用这个纸支架，再装饰它。"}],"patterns":[{"pattern":"动词原形 + ...","meaning":"用祈使句说明制作步骤","example":"Fold the card in half and draw a line.","translation":"把卡纸对折，再画一条线。","tip":"祈使句通常省略主语 you，直接以动词原形开头。"},{"pattern":"Do not + 动词原形 ...","meaning":"提醒对方不要做某事","example":"Do not add the labels before the paint dries.","translation":"油漆干之前不要贴标签。","tip":"否定祈使句用 Do not / Don't 加动词原形。"},{"pattern":"You should / had better + 动词原形 ...","meaning":"提出制作建议","example":"You had better test the stand with an empty cup first.","translation":"你最好先用空杯子测试这个支架。","tip":"had better 后接动词原形；否定形式是 had better not do。"}]},{"unitId":"8a-u5","phrases":[{"phrase":"in the wild","meaning":"在野外","example":"We hope to observe birds in the wild.","translation":"我们希望在野外观察鸟类。"},{"phrase":"keep a distance from","meaning":"与……保持距离","example":"Visitors keep a distance from the resting animals.","translation":"访客与正在休息的动物保持距离。"},{"phrase":"in danger","meaning":"处于危险中","example":"Some wild animals are in danger because their habitats are disappearing.","translation":"一些野生动物因为栖息地正在消失而处于危险中。"},{"phrase":"write down","meaning":"记下","example":"We write down the time and place of each observation.","translation":"我们记下每次观察的时间和地点。"}],"patterns":[{"pattern":"主语 + plan / hope + to do ...","meaning":"说明观察计划或愿望","example":"Our group plans to watch birds from the marked path.","translation":"我们小组计划从有标记的小路上观察鸟类。","tip":"plan、hope 后可接 to do；不能在 to 后用 watching。"},{"pattern":"主语 + agree + not to do ...","meaning":"说明约定不做的事","example":"We agree not to play recorded bird calls.","translation":"我们约定不播放录制的鸟叫声。","tip":"不定式的否定形式通常是 not to do。"},{"pattern":"... to + 动词原形 ...","meaning":"用不定式说明目的","example":"We bring notebooks to record what we see.","translation":"我们带上笔记本来记录所见。","tip":"to record 表示带笔记本的目的；主句和目的动作的执行者均为 we。"}]},{"unitId":"8a-u6","phrases":[{"phrase":"be covered with","meaning":"被……覆盖","example":"The garden is covered with snow in this photograph.","translation":"这张照片中的花园被雪覆盖。"},{"phrase":"a gust of wind","meaning":"一阵风","example":"A gust of wind sends dry leaves across the path.","translation":"一阵风把干叶子吹过小路。"},{"phrase":"from ... to ...","meaning":"从……到……","example":"The leaves change from green to yellow in autumn.","translation":"叶子在秋天从绿色变成黄色。"},{"phrase":"in full bloom","meaning":"盛开","example":"The trees near our classroom are in full bloom.","translation":"我们教室附近的树开满了花。"}],"patterns":[{"pattern":"主语 + 连系动词 + 表语.","meaning":"描述季节景象的状态","example":"The air feels cool after the autumn rain.","translation":"秋雨过后，空气让人感觉凉爽。","tip":"feel 在这里是连系动词，后接形容词 cool。"},{"pattern":"主语 + 谓语 + 宾语.","meaning":"描述人对季节事物的动作","example":"Children collect fallen leaves beside the path.","translation":"孩子们在小路旁收集落叶。","tip":"Children 是主语，collect 是谓语，fallen leaves 是宾语。"},{"pattern":"主语 + 谓语 + 间接宾语 + 直接宾语.","meaning":"描述把某物给某人","example":"My sister shows me her winter photographs.","translation":"姐姐给我看她的冬日照片。","tip":"me 指接收者，her winter photographs 指展示的内容。"}]},{"unitId":"8a-u7","phrases":[{"phrase":"feed on","meaning":"以……为食","example":"Some small birds feed on insects in the garden.","translation":"一些小鸟以花园中的昆虫为食。"},{"phrase":"be home to","meaning":"是……的栖息地","example":"Our school pond is home to several kinds of insects.","translation":"我们学校的池塘是几种昆虫的栖息地。"},{"phrase":"depend on","meaning":"依靠；取决于","example":"Many garden animals depend on plants for food.","translation":"许多花园里的动物依靠植物获取食物。"},{"phrase":"keep a record of","meaning":"记录……","example":"We keep a record of changes in the nature corner.","translation":"我们记录自然角的变化。"}],"patterns":[{"pattern":"... because ...","meaning":"说明观察活动的原因","example":"We return at the same time because we want to compare our notes.","translation":"我们在同一时间再次来观察，因为我们想比较笔记。","tip":"because 引导原因；此类句子一般不再搭配 so 连接结果。"},{"pattern":"... and ... / ... but ...","meaning":"连接并列或转折的信息","example":"The pond looks quiet, but many small animals live there.","translation":"池塘看起来很安静，但是那里生活着许多小动物。","tip":"and 表示并列，but 表示转折；先判断两部分的关系。"},{"pattern":"主语 + 谓语 + 宾语 + 宾语补足语.","meaning":"描述某事使对象处于某状态","example":"The new sign keeps the path clear.","translation":"新标牌让小路保持畅通。","tip":"clear 补充说明宾语 the path 的状态，不是修饰 keep 的副词。"}]},{"unitId":"8a-u8","phrases":[{"phrase":"stay calm","meaning":"保持冷静","example":"We try to stay calm during the school drill.","translation":"我们在学校演练时努力保持冷静。"},{"phrase":"take shelter","meaning":"躲避风雨等；寻找庇护","example":"The group took shelter in the school hall.","translation":"小组到学校礼堂里避雨。"},{"phrase":"check on","meaning":"查看……的情况","example":"The teacher checked on each group after the drill.","translation":"演练结束后，老师查看了每个小组的情况。"},{"phrase":"follow instructions","meaning":"遵照指示","example":"All the students followed the teacher's instructions.","translation":"所有学生都遵照老师的指示行动。"}],"patterns":[{"pattern":"主语 + was / were + 动词-ing ...","meaning":"描述过去某时正在进行的活动","example":"We were drawing in the classroom at ten yesterday.","translation":"昨天十点我们正在教室里画画。","tip":"过去进行时用 was / were 加 -ing；we 对应 were。"},{"pattern":"... was / were doing ... when ... happened.","meaning":"描述一个动作进行时另一件事发生","example":"I was checking the list when the teacher called my name.","translation":"老师叫我名字时，我正在核对名单。","tip":"持续的背景动作常用过去进行时；突然发生的动作常用一般过去时。"},{"pattern":"While ... was / were doing ..., ... was / were doing ...","meaning":"描述过去同时进行的动作","example":"While I was counting the bags, Ben was checking the names.","translation":"我在清点书包时，本在核对姓名。","tip":"while 可连接两个在过去同一时段持续进行的动作。"}]},{"unitId":"8b-u1","phrases":[{"phrase":"used to do something","meaning":"过去常做某事","example":"People used to buy tickets in this small building.","translation":"人们过去常在这座小楼里买票。"},{"phrase":"change into","meaning":"变成……","example":"The old waiting room has changed into a reading space.","translation":"旧候车室已经变成了阅读空间。"},{"phrase":"in the past","meaning":"在过去","example":"There were fewer shops here in the past.","translation":"过去这里的商店更少。"},{"phrase":"over the years","meaning":"多年来","example":"Our neighbourhood has become greener over the years.","translation":"多年来，我们的社区变得更绿了。"}],"patterns":[{"pattern":"主语 + have / has + 过去分词 ...","meaning":"描述与现在有关的变化","example":"The old station has become a community library.","translation":"旧车站已经变成了一座社区图书馆。","tip":"现在完成时需要 have / has 和过去分词；become 的过去分词仍是 become。"},{"pattern":"主语 + have / has not + 过去分词 ...","meaning":"说明尚未发生的变化","example":"The town has not removed the old clock.","translation":"小镇还没有拆掉那座旧钟。","tip":"has not 可缩写为 hasn't；否定的是到现在为止的情况。"},{"pattern":"Have / Has + 主语 + 过去分词 ...?","meaning":"询问到现在是否发生了变化","example":"Has the street changed since your last visit?","translation":"自从你上次来访后，这条街有变化吗？","tip":"since 引出过去的时间起点，主句可用现在完成时。"}]},{"unitId":"8b-u2","phrases":[{"phrase":"places of interest","meaning":"名胜","example":"We marked three places of interest on our map.","translation":"我们在地图上标出了三处名胜。"},{"phrase":"be away from","meaning":"离开……；不在……","example":"My cousin has been away from home for five days.","translation":"我表姐已经离家五天了。"},{"phrase":"have been to","meaning":"去过某地（现已返回）","example":"I have been to Nanjing with my family.","translation":"我和家人去过南京。"},{"phrase":"at the end of","meaning":"在……结束时；在……的尽头","example":"We bought a postcard at the end of the trip.","translation":"我们在旅程结束时买了一张明信片。"}],"patterns":[{"pattern":"主语 + have / has been to ...","meaning":"介绍曾经去过的地方","example":"Our class has been to the local history museum.","translation":"我们班去过本地的历史博物馆。","tip":"have been to 强调去过并已返回；have gone to 常表示去了尚未返回。"},{"pattern":"主语 + have / has been + 状态 + for + 时长.","meaning":"说明持续到现在的状态","example":"We have been in this city for two days.","translation":"我们已经在这座城市待了两天。","tip":"持续一段时间用状态表达 have been in；不用 have arrived for two days。"},{"pattern":"主语 + have / has + 过去分词 ... since + 过去时间点.","meaning":"说明从过去某时持续到现在","example":"I have kept this travel diary since last spring.","translation":"从去年春天起，我一直保留着这本旅行日记。","tip":"since 接起点，for 接时长；keep 的过去分词是 kept。"}]},{"unitId":"8b-u3","phrases":[{"phrase":"take a virtual tour","meaning":"进行虚拟参观","example":"We took a virtual tour of a museum yesterday.","translation":"我们昨天虚拟参观了一座博物馆。"},{"phrase":"check the source","meaning":"核查来源","example":"I check the source before using an online photograph.","translation":"我在使用网络照片前核查来源。"},{"phrase":"up to date","meaning":"最新的；包含最新信息的","example":"The visitor information is up to date.","translation":"这份访客信息是最新的。"},{"phrase":"find out","meaning":"查明；弄清","example":"We want to find out when the page was updated.","translation":"我们想查明这个网页何时更新的。"}],"patterns":[{"pattern":"主语 + have / has already + 过去分词 ...","meaning":"说明到现在已经完成的事","example":"I have already checked the date on the museum page.","translation":"我已经核查了博物馆网页上的日期。","tip":"already 常放在 have / has 后、过去分词前。"},{"pattern":"主语 + 动词过去式 + 明确过去时间.","meaning":"说明某个过去时点的活动","example":"I visited the museum website last night.","translation":"我昨晚访问了博物馆网站。","tip":"last night 是已结束的过去时间，通常用一般过去时。"},{"pattern":"主语 + have / has not + 过去分词 ... yet.","meaning":"说明截至现在还未完成的事","example":"We have not found the original photograph yet.","translation":"我们还没有找到原始照片。","tip":"yet 常放在现在完成时否定句末，表示还未。"}]},{"unitId":"8b-u4","phrases":[{"phrase":"choose between","meaning":"在……之间选择","example":"Our club must choose between two short novels.","translation":"我们社团必须在两部短篇小说之间选择。"},{"phrase":"give away the ending","meaning":"泄露结局","example":"My review does not give away the ending.","translation":"我的书评不泄露结局。"},{"phrase":"hand in","meaning":"提交；上交","example":"We hand in our reading notes on Friday.","translation":"我们周五提交阅读笔记。"},{"phrase":"return ... on time","meaning":"按时归还……","example":"Please return the library books on time.","translation":"请按时归还图书馆的书。"}],"patterns":[{"pattern":"疑问词 + to do","meaning":"用简洁结构表达要做什么或怎样做","example":"I am not sure which book to choose.","translation":"我不确定该选哪本书。","tip":"which book to choose 是疑问词加不定式结构，作 sure 后的补足内容。"},{"pattern":"主语 + must + 动词原形 ...","meaning":"说明必须遵守的要求","example":"We must return these books by Friday.","translation":"我们必须在周五之前归还这些书。","tip":"must 表示必须；此处 by Friday 表示不晚于周五。"},{"pattern":"主语 + do / does not have to + 动词原形 ...","meaning":"说明没有必要做某事","example":"You do not have to finish the whole novel tonight.","translation":"你不必今晚读完整部小说。","tip":"do not have to 表示不必；must not 表示禁止，两者意义不同。"}]},{"unitId":"8b-u5","phrases":[{"phrase":"wait one's turn","meaning":"等候轮到自己","example":"We wait our turn before asking the guide a question.","translation":"我们等轮到自己时再向导游提问。"},{"phrase":"lower one's voice","meaning":"压低声音","example":"I lower my voice near the reading area.","translation":"我在阅读区附近压低声音。"},{"phrase":"in public","meaning":"在公共场合","example":"We consider other people's needs in public.","translation":"我们在公共场合考虑别人的需要。"},{"phrase":"excuse me","meaning":"劳驾；对不起（引起注意等）","example":"Excuse me, may I take a photo of your work?","translation":"劳驾，我可以给您的作品拍照吗？"}],"patterns":[{"pattern":"... is + 形容词 + enough to do ...","meaning":"表达达到做某事的程度","example":"The label is clear enough to read from here.","translation":"这张标签够清楚，从这里就能读到。","tip":"enough 放在形容词 clear 后；to read 说明达到的程度。"},{"pattern":"... is too + 形容词 + to do ...","meaning":"表达太……而不能……","example":"The room is too crowded to hold another group.","translation":"房间太拥挤，容不下另一组人。","tip":"too ... to ... 表达程度超过限度，不能再做后面的事。"},{"pattern":"... is not + 形容词 + enough to do ...","meaning":"表达尚未达到做某事的程度","example":"My voice is not loud enough to reach the back row.","translation":"我的声音不够响，后排听不见。","tip":"not ... enough to ... 表示程度不足；结合实际情境调整音量。"}]},{"unitId":"8b-u6","phrases":[{"phrase":"volunteer to do something","meaning":"自愿做某事","example":"I volunteer to read stories at the community centre.","translation":"我自愿在社区中心读故事。"},{"phrase":"ask about needs","meaning":"询问需求","example":"We ask about needs before planning the reading session.","translation":"我们在安排阅读活动前询问需求。"},{"phrase":"work as a team","meaning":"作为团队合作","example":"The volunteers work as a team to prepare the room.","translation":"志愿者们合作准备活动室。"},{"phrase":"get feedback from","meaning":"从……获得反馈","example":"We get feedback from the readers after each session.","translation":"每次活动后，我们都向读者收集反馈。"}],"patterns":[{"pattern":"It is + 形容词 + for somebody + to do ...","meaning":"评价某人做某事的难易或必要性","example":"It is important for us to ask what readers enjoy.","translation":"询问读者喜欢什么对我们很重要。","tip":"for 引出动作执行者；important 评价事情的重要性。"},{"pattern":"It is + 形容词 + of somebody + to do ...","meaning":"通过行为评价人的品质","example":"It is kind of you to prepare larger print for me.","translation":"你为我准备大字号文本，真体贴。","tip":"kind 评价人的品质，通常用 of somebody。"},{"pattern":"主语 + is / are ready to do ...","meaning":"表示准备好承担任务","example":"Our team is ready to change the plan after hearing suggestions.","translation":"听取建议后，我们团队准备调整计划。","tip":"ready 后接 to do；说明愿意采取的具体行动。"}]},{"unitId":"8b-u7","phrases":[{"phrase":"raise money for","meaning":"为……筹款","example":"The class raised money for the reading project.","translation":"班级为阅读项目筹集了资金。"},{"phrase":"sort ... into ...","meaning":"把……分类为……","example":"Volunteers sorted the books into three groups.","translation":"志愿者把书分成了三类。"},{"phrase":"be in good condition","meaning":"状况良好","example":"The donated dictionaries are in good condition.","translation":"捐赠的词典保存状况良好。"},{"phrase":"keep track of","meaning":"跟踪记录……","example":"We keep track of every box sent to the centre.","translation":"我们跟踪记录送到中心的每个箱子。"}],"patterns":[{"pattern":"主语 + am / is / are + 过去分词 ...","meaning":"说明经常进行的处理流程","example":"The donated books are checked by student volunteers.","translation":"捐赠的书由学生志愿者检查。","tip":"一般现在时被动语态用 am / is / are 加过去分词。"},{"pattern":"主语 + was / were + 过去分词 ...","meaning":"说明过去已经完成的公益工作","example":"Thirty books were delivered to the centre yesterday.","translation":"三十本书昨天被送到了中心。","tip":"过去时间 yesterday 对应 was / were；复数 books 用 were。"},{"pattern":"主语 + was / were + 过去分词 + by ...","meaning":"说明过去动作的执行者","example":"The collection list was prepared by our class monitor.","translation":"募集清单由我们班长制作。","tip":"by 后说明执行者；被动句强调的是清单的处理情况。"}]},{"unitId":"8b-u8","phrases":[{"phrase":"reduce waste","meaning":"减少浪费；减少废弃物","example":"We bring reusable cups to reduce waste.","translation":"我们带可重复使用的杯子来减少废弃物。"},{"phrase":"separate ... from ...","meaning":"把……与……分开","example":"Please separate clean paper from food waste.","translation":"请把干净纸张与厨余垃圾分开。"},{"phrase":"make use of","meaning":"利用","example":"Our class will make use of the old display boards.","translation":"我们班将利用旧展示板。"},{"phrase":"check the results","meaning":"检查结果","example":"The team will check the results after the fair.","translation":"小组将在义卖会后检查结果。"}],"patterns":[{"pattern":"主语 + will be + 过去分词 ...","meaning":"说明计划中将被完成的行动","example":"Reusable cups will be provided at the class fair.","translation":"班级义卖会上将提供可重复使用的杯子。","tip":"一般将来时被动语态用 will be 加过去分词，be 不能省略。"},{"pattern":"主语 + will not be + 过去分词 ...","meaning":"说明计划中不会被采取的做法","example":"Single-use decorations will not be bought for this event.","translation":"这次活动将不购买一次性装饰品。","tip":"否定形式是 will not be done；will not 可缩写为 won't。"},{"pattern":"Will + 主语 + be + 过去分词 ...?","meaning":"询问将来的处理安排","example":"Will the paper signs be reused next term?","translation":"这些纸标牌下学期会被再次使用吗？","tip":"将 will 提到主语前，保留 be 和过去分词 reused。"}]},{"unitId":"9a-u1","phrases":[{"phrase":"work as a team","meaning":"作为一个团队合作","example":"We worked as a team and tested everyone's bridge design.","translation":"我们作为一个团队合作，测试了每个人的桥梁设计。"},{"phrase":"take the lead","meaning":"带头；担任领导角色","example":"Mei took the lead in the discussion but gave everyone time to speak.","translation":"梅主持了讨论，但给了每个人发言的时间。"},{"phrase":"be patient with","meaning":"对……有耐心","example":"A good partner is patient with someone who needs more practice.","translation":"好的搭档会耐心对待需要更多练习的人。"},{"phrase":"recognize a strength","meaning":"发现并认可一项长处","example":"The interview helped me recognize a strength I had never noticed.","translation":"这次采访帮助我发现了一项自己以前从未注意到的长处。"}],"patterns":[{"pattern":"Both ... and ...","meaning":"……和……都……","example":"Both careful listening and clear planning help our team succeed.","translation":"认真倾听和清晰规划都有助于我们的团队取得成功。","tip":"连接两个并列成分；连接两个主语时，谓语通常用复数形式。"},{"pattern":"Neither ... nor ...","meaning":"既不……也不……","example":"Neither the leader nor the other members want to ignore a useful idea.","translation":"组长和其他成员都不想忽视有用的想法。","tip":"连接主语时，谓语形式通常与较近的主语一致；本句靠近谓语的是复数 members。"},{"pattern":"not only ... but also ...","meaning":"不仅……而且……","example":"Jin not only organized the materials but also encouraged the quieter students.","translation":"金不仅整理了材料，还鼓励了比较安静的同学。","tip":"两部分尽量连接结构相同的成分；本句连接 organized 和 encouraged 两个过去式动词。"}]},{"unitId":"9a-u2","phrases":[{"phrase":"be under pressure","meaning":"承受压力","example":"I am under pressure when several projects are due in the same week.","translation":"当几个项目都要在同一周交时，我会感到有压力。"},{"phrase":"ask for advice","meaning":"征求建议","example":"Lara asked for advice before changing her study plan.","translation":"拉拉在改变学习计划前征求了建议。"},{"phrase":"clear up a misunderstanding","meaning":"消除误会","example":"A short conversation helped the two partners clear up a misunderstanding.","translation":"一次简短的交谈帮助两位搭档消除了误会。"},{"phrase":"work out a solution","meaning":"想出解决办法","example":"We worked out a solution after checking the missing instructions.","translation":"核对了遗漏的要求后，我们想出了解决办法。"}],"patterns":[{"pattern":"Could you tell me + 疑问词引导的宾语从句?","meaning":"你能告诉我……吗？","example":"Could you tell me how many examples we need for the poster?","translation":"你能告诉我这张海报需要多少个例子吗？","tip":"宾语从句用陈述语序：how many examples we need，不能写成 how many examples do we need。"},{"pattern":"I wonder whether ...","meaning":"我想知道是否……","example":"I wonder whether my partner has seen the revised plan.","translation":"我想知道我的搭档是否看过修改后的计划。","tip":"whether 表示“是否”；从句有自己的主语和谓语，本句用 has seen 表示与现在有关的情况。"},{"pattern":"Do you know why + 主语 + 谓语 ...?","meaning":"你知道……为什么……吗？","example":"Do you know why the meeting time has changed?","translation":"你知道会议时间为什么变了吗？","tip":"整个句子是问句，但 why 后的宾语从句仍用陈述语序，不把 has 提到主语前。"}]},{"unitId":"9a-u3","phrases":[{"phrase":"keep a record of","meaning":"记录……","example":"Arun keeps a record of the decisions he makes during each game.","translation":"阿伦记录自己在每盘棋中作出的决定。"},{"phrase":"learn from mistakes","meaning":"从错误中学习","example":"We learn from mistakes by finding out why they happened.","translation":"我们通过弄清错误发生的原因来从中学习。"},{"phrase":"make steady progress","meaning":"取得稳步进步","example":"With short daily practice, Rui made steady progress in speaking.","translation":"通过每天简短的练习，瑞的口语取得了稳步进步。"},{"phrase":"break a task into smaller steps","meaning":"把一项任务分成较小的步骤","example":"Our coach helped us break the task into smaller steps.","translation":"教练帮助我们把这项任务分成了较小的步骤。"}],"patterns":[{"pattern":"As soon as + 从句, 主句.","meaning":"一……就……","example":"As soon as the practice ends, I will write down one thing to improve.","translation":"练习一结束，我就会记下一点需要改进的地方。","tip":"谈论将来的时间关系时，as soon as 从句常用一般现在时，主句可用 will。"},{"pattern":"主句 + before + 从句.","meaning":"在……之前……","example":"Arun checks his opponent's pieces before he makes a move.","translation":"阿伦在走棋之前会查看对手的棋子。","tip":"before 引导时间从句；这里描述习惯，主句和从句都用一般现在时。"},{"pattern":"主语 + did not ... until ...","meaning":"直到……才……","example":"I did not notice my repeated mistake until I watched the recording.","translation":"直到看了录像，我才注意到自己反复犯的错误。","tip":"not ... until 表示某动作到该时间才发生；过去的具体经历中注意主从句的过去时。"}]},{"unitId":"9a-u4","phrases":[{"phrase":"take a closer look","meaning":"更仔细地看一看","example":"Jun took a closer look and found tiny plants beside the wall.","translation":"俊更仔细地看了看，发现墙边有一些小植物。"},{"phrase":"be full of life","meaning":"充满生机","example":"The small courtyard was full of life after the spring rain.","translation":"春雨过后，小院充满了生机。"},{"phrase":"slow down","meaning":"放慢速度","example":"When I slowed down, I noticed the patterns on the fallen leaves.","translation":"当我放慢脚步时，我注意到了落叶上的纹理。"},{"phrase":"notice small details","meaning":"注意到细小的细节","example":"Drawing the old bench helped us notice small details in its wood.","translation":"画那张旧长椅帮助我们注意到了木头上的细小细节。"}],"patterns":[{"pattern":"主语 + be + -ed形容词 + by ...","meaning":"……因……而产生某种感受","example":"We were amazed by the changing colours of the evening sky.","translation":"傍晚天空不断变化的色彩让我们感到惊叹。","tip":"amazed 描述感受到的状态，amazing 描述令人惊叹的性质；不要只按人或物选择词形。"},{"pattern":"名词 + 动词-ing短语","meaning":"用主动进行的动作修饰名词","example":"The girl sketching beside the pond noticed a dragonfly.","translation":"在池塘边画速写的女孩注意到了一只蜻蜓。","tip":"sketching beside the pond 后置修饰 girl，表示女孩正在做的动作。"},{"pattern":"名词 + 过去分词短语","meaning":"用过去分词短语说明名词承受的动作或状态","example":"The bench repaired by our neighbours looks beautiful in the morning light.","translation":"邻居们修好的那张长椅在晨光中显得很美。","tip":"repaired by our neighbours 后置修饰 bench，长椅是 repair 的承受者。"}]},{"unitId":"9a-u5","phrases":[{"phrase":"bring back memories","meaning":"唤起回忆","example":"The gentle piano tune brought back memories of a train journey.","translation":"轻柔的钢琴曲唤起了我对一次火车旅行的回忆。"},{"phrase":"express personal feelings","meaning":"表达个人感受","example":"Pei used a slow melody to express personal feelings about leaving home.","translation":"佩用缓慢的旋律表达自己离家时的个人感受。"},{"phrase":"keep the beat","meaning":"保持节拍；跟上节拍","example":"We tapped the table softly to keep the beat during practice.","translation":"练习时，我们轻轻敲着桌子来保持节拍。"},{"phrase":"remind somebody of something","meaning":"使某人想起某事物","example":"The low notes remind me of rain falling on the roof.","translation":"这些低音使我想起雨落在屋顶上的声音。"}],"patterns":[{"pattern":"主句 + because + 原因从句.","meaning":"因为……，所以……","example":"I imagined a quiet lake because the melody moved slowly and smoothly.","translation":"我想象到一片宁静的湖泊，因为旋律缓慢而流畅。","tip":"because 后接有主语和谓语的从句；同一句中通常不再用 so 连接主句。"},{"pattern":"Since + 已知原因, 主句.","meaning":"既然……，就……","example":"Since the poem describes a peaceful evening, we chose soft background music.","translation":"既然这首诗描写的是宁静的夜晚，我们就选了轻柔的背景音乐。","tip":"since 在这里表示原因，提出双方已知或容易接受的依据，并非表示“自从”。"},{"pattern":"As + 原因从句, 主句.","meaning":"由于……，……","example":"As the drums were louder than the reader's voice, we lowered the volume.","translation":"由于鼓声比朗读者的声音还响，我们调低了音量。","tip":"as 在这里引出原因；要结合上下文区分它表示“当……时”等其他用法。"}]},{"unitId":"9a-u6","phrases":[{"phrase":"draw attention to","meaning":"使人注意……","example":"The label draws attention to the artist's use of empty space.","translation":"这张说明牌让人注意到艺术家对留白的运用。"},{"phrase":"practise brush strokes","meaning":"练习笔画","example":"Han practised brush strokes before writing the whole character.","translation":"韩在写整个字之前先练习了笔画。"},{"phrase":"on display","meaning":"在展出；在陈列","example":"Both the practice sheets and the finished work are on display.","translation":"练习稿和完成的作品都在展出。"},{"phrase":"show the creative process","meaning":"展示创作过程","example":"The notes show the creative process behind this simple-looking painting.","translation":"这些笔记展示了这幅看似简单的画背后的创作过程。"}],"patterns":[{"pattern":"表示人的名词 + who + 谓语 ...","meaning":"用定语从句说明做某事的人","example":"The student who designed the label wanted visitors to notice the lighter lines.","translation":"设计说明牌的那位学生希望参观者注意到较淡的线条。","tip":"who 指代 student，并在从句中作主语，因此不能省略。"},{"pattern":"表示物的名词 + which/that + 谓语 ...","meaning":"用定语从句说明具有某种特点的事物","example":"The painting that hangs beside the window uses only three colours.","translation":"挂在窗边的那幅画只用了三种颜色。","tip":"that 在从句中作 hangs 的主语；从句说明的是 painting，不要再重复加 it。"},{"pattern":"名词 + (that/which) + 主语 + 谓语 ...","meaning":"用定语从句说明某人所做动作涉及的事物","example":"The practice sheet that Han kept shows how his brushwork changed.","translation":"韩保留的那张练习稿展示了他的笔法如何变化。","tip":"that 指代 sheet，在 kept 后作宾语；此处可省略，但不要在 kept 后再加 it。"}]},{"unitId":"9a-u7","phrases":[{"phrase":"give away the ending","meaning":"泄露结局","example":"A useful review can discuss the film without giving away the ending.","translation":"一篇有用的影评可以讨论电影而不泄露结局。"},{"phrase":"support an opinion","meaning":"支持一个观点","example":"Choose one clear example from the film to support your opinion.","translation":"从影片中选一个清楚的例子来支持你的观点。"},{"phrase":"in the final scene","meaning":"在最后一个场景中","example":"In the final scene, the camera stays on the empty doorway.","translation":"在最后一个场景中，镜头停留在空荡荡的门口。"},{"phrase":"be worth watching","meaning":"值得观看","example":"The short film is worth watching for its careful use of light.","translation":"这部短片对光线的细致运用使它值得一看。"}],"patterns":[{"pattern":"Although/Though + 从句, 主句.","meaning":"虽然……，但是……","example":"Although the story is simple, the actors make the characters believable.","translation":"虽然故事简单，但演员们让人物显得可信。","tip":"although 或 though 引导让步从句；同一句中通常不再用 but 连接主句。"},{"pattern":"so + 形容词/副词 + that + 结果从句","meaning":"如此……以至于……","example":"The music was so loud that I missed an important line.","translation":"音乐声太响了，以至于我漏听了一句重要的台词。","tip":"so 修饰 loud，that 后说明实际结果；不要与表示目的的 so that 混淆。"},{"pattern":"主句 + so that + 主语 + can/could ...","meaning":"……以便……","example":"We watched the scene again so that we could check our comments.","translation":"我们又看了一遍那个片段，以便核对自己的评论。","tip":"这里 so that 引导目的从句；主句是过去时，从句用 could 与之呼应。"}]},{"unitId":"9a-u8","phrases":[{"phrase":"make a choice","meaning":"作出选择","example":"The young character must make a choice before the last boat leaves.","translation":"年轻的主人公必须在最后一班船离开前作出选择。"},{"phrase":"leave a clue","meaning":"留下线索","example":"The writer leaves a clue in the first paragraph about the missing letter.","translation":"作者在第一段为那封失踪的信留下了一条线索。"},{"phrase":"fit the story","meaning":"符合故事情节","example":"A talking tree may not fit the story unless magic appears earlier.","translation":"除非前文已经出现魔法，否则一棵会说话的树可能不符合这个故事的情节。"},{"phrase":"lead to a different ending","meaning":"导致一个不同的结局","example":"One honest answer could lead to a different ending.","translation":"一个诚实的回答可能会带来一个不同的结局。"}],"patterns":[{"pattern":"If + 一般现在时, 主语 + will + 动词原形 ...","meaning":"如果……，将会……","example":"If the boy returns the letter, his neighbour will learn the truth.","translation":"如果男孩归还那封信，他的邻居就会知道真相。","tip":"表示可能发生的未来情况时，if 从句通常用一般现在时，不因主句有 will 就也加 will。"},{"pattern":"Unless + 肯定形式的从句, 主句.","meaning":"除非……；如果不……","example":"Unless the writer adds an earlier clue, the sudden rescue will seem unlikely.","translation":"除非作者在前文加入线索，否则这次突然的营救会显得不太可信。","tip":"unless 通常相当于 if ... not；本句不要再在 adds 前加 not。"},{"pattern":"If + 条件从句, 主语 + can + 动词原形 ...","meaning":"如果……，就可以……","example":"If a new scene reveals the girl's reason, readers can understand her choice better.","translation":"如果新增的场景揭示了女孩的理由，读者就能更好地理解她的选择。","tip":"条件句的主句也可用 can 等情态动词；依据实际含义选择，不必一律用 will。"}]},{"unitId":"9b-u1","phrases":[{"phrase":"provide context","meaning":"提供背景信息","example":"The date and the photographer's notes provide context for the travel pictures.","translation":"日期和摄影者的笔记为这些旅行照片提供了背景信息。"},{"phrase":"label a photograph","meaning":"给照片加上说明","example":"We labelled each photograph with its place and date.","translation":"我们为每张照片标注了地点和日期。"},{"phrase":"learn about local customs","meaning":"了解当地习俗","example":"The exchange students asked questions to learn about local customs.","translation":"交换生们通过提问来了解当地习俗。"},{"phrase":"from personal experience","meaning":"根据亲身经历","example":"Mina spoke from personal experience when she described her visit to the market.","translation":"米娜描述自己逛市场的见闻时，依据的是亲身经历。"}],"patterns":[{"pattern":"It is + 距离 + from ... to ...","meaning":"从……到……有……远","example":"On our display map, it is about two kilometres from the station to the museum.","translation":"在我们的展览地图上，车站到博物馆大约有两公里。","tip":"表示距离时用 it 作主语；这里的 it 无需译成某个具体物品。"},{"pattern":"It was + 描述天气的形容词 + 时间状语.","meaning":"某个时候天气……","example":"It was cloudy on the morning when our host family showed us the old streets.","translation":"寄宿家庭带我们游览老街的那个早晨，天气多云。","tip":"描述天气时保留主语 it；讲述过去的旅行经历，用 was。"},{"pattern":"It is + 形容词 + for somebody + to do ...","meaning":"对某人来说，做……是……的","example":"It is helpful for visitors to know when and where a photograph was taken.","translation":"了解照片拍摄的时间和地点对参观者很有帮助。","tip":"it 是形式主语，真正谈论的事情是后面的 to know ...；for visitors 说明动作涉及的人。"}]},{"unitId":"9b-u2","phrases":[{"phrase":"make a contribution","meaning":"作出贡献","example":"Every volunteer made a contribution to the community repair project.","translation":"每位志愿者都为社区修缮项目作出了贡献。"},{"phrase":"solve a practical problem","meaning":"解决实际问题","example":"The engineer listened to residents before trying to solve a practical problem.","translation":"这位工程师在尝试解决实际问题前先倾听了居民的意见。"},{"phrase":"share the credit","meaning":"分享功劳；共同获得肯定","example":"The designer chose to share the credit with the team that tested her idea.","translation":"设计师选择与测试她的想法的团队分享功劳。"},{"phrase":"learn from others","meaning":"向他人学习","example":"Even an experienced inventor needs to learn from others.","translation":"即使是经验丰富的发明者也需要向他人学习。"}],"patterns":[{"pattern":"主语 + 一般现在时谓语 ...","meaning":"描述人物现在的习惯或通常的工作","example":"Ms Lin visits the workshop every Friday and listens to the volunteers' suggestions.","translation":"林女士每周五都去工作坊，听取志愿者们的建议。","tip":"every Friday 表示习惯；第三人称单数主语后用 visits 和 listens。"},{"pattern":"主语 + was/were doing ... when + 一般过去时从句.","meaning":"正在做……时，发生了另一件事","example":"The engineer was checking the model when a student noticed a loose part.","translation":"工程师正在检查模型时，一名学生发现了一个松动的零件。","tip":"was checking 交代当时正在进行的背景，noticed 表示那时发生的具体动作。"},{"pattern":"主语 + have/has + 过去分词 ... since + 过去时间点.","meaning":"自从过去某时起一直……","example":"She has worked with the community team since 2022.","translation":"自2022年以来，她一直与社区团队合作。","tip":"现在完成时表示从过去持续到现在；since 后接起点，不能把主句简单改成过去式而仍表达持续至今。"}]},{"unitId":"9b-u3","phrases":[{"phrase":"ask for human help","meaning":"请求人工帮助","example":"In our design, the robot stops to ask for human help when a label is unreadable.","translation":"在我们的设计中，标签无法辨认时，机器人会停下来请求人工帮助。"},{"phrase":"follow a fixed rule","meaning":"遵循固定规则","example":"The fictional robot follows a fixed rule instead of judging the content of a book.","translation":"这个虚构的机器人遵循固定规则，而不是判断书的内容。"},{"phrase":"carry out a task","meaning":"执行任务","example":"We used empty boxes to test how the helper would carry out its task.","translation":"我们用空盒子测试这个助手会如何执行任务。"},{"phrase":"deal with an unusual case","meaning":"处理不寻常的情况","example":"A librarian still needs to deal with an unusual case that the rules do not cover.","translation":"规则未涵盖的不寻常情况仍需要图书管理员处理。"}],"patterns":[{"pattern":"know + 疑问词 + to do ...","meaning":"知道该做什么、如何做等","example":"The operator needs to know how to stop the robot during a test.","translation":"操作员需要知道测试期间如何让机器人停止运行。","tip":"how to stop 可对应 how the operator should stop；转换时要确保 stop 的执行者仍是 operator。"},{"pattern":"主语 + 动词 ... + in order to do ...","meaning":"……以便做……","example":"We checked every label in order to reduce sorting mistakes.","translation":"我们检查了每一张标签，以减少分类错误。","tip":"可改为 so that we could reduce sorting mistakes；两句中检查和减少错误的执行者都是 we。"},{"pattern":"too + 形容词 + for somebody + to do ...","meaning":"太……，以至于某人无法做……","example":"The label is too damaged for the operator to read.","translation":"标签破损得太严重，操作员无法辨认。","tip":"可对应 The label is so damaged that the operator cannot read it；不定式中的 read 不再重复宾语 it。"}]},{"unitId":"9b-u4","phrases":[{"phrase":"adapt to a new routine","meaning":"适应新的日常安排","example":"In our story, the new resident needs time to adapt to a new routine.","translation":"在我们的故事中，新居民需要时间适应新的日常安排。"},{"phrase":"respect other people's needs","meaning":"尊重他人的需求","example":"The fictional residents learn to respect other people's needs when sharing a room.","translation":"这些虚构的居民在共用房间时学着尊重他人的需求。"},{"phrase":"keep in touch with","meaning":"与……保持联系","example":"Niko prepares messages to keep in touch with his family in the story.","translation":"故事中的尼科准备发送信息，与家人保持联系。"},{"phrase":"share a common space","meaning":"共用一个公共空间","example":"Our characters make a timetable so that they can share a common space fairly.","translation":"我们笔下的人物制定时间表，以便公平地共用一个公共空间。"}],"patterns":[{"pattern":"主句 + because of + 名词短语.","meaning":"因为……而……","example":"In the story, Niko leaves the shared room because of the noise.","translation":"在故事中，尼科因为噪声离开了共用房间。","tip":"可改为 ... because it is noisy；because of 后接名词短语，不能直接接 it is noisy 这样的从句。"},{"pattern":"Before + 动词-ing短语, 主语 + 谓语 ...","meaning":"在做……之前，……","example":"Before recording a message, Niko checks whether anyone else needs the study room.","translation":"录制信息前，尼科先确认是否还有其他人需要用阅览室。","tip":"可改为 Before Niko records a message, ...；recording 的执行者必须与主句主语 Niko 一致。"},{"pattern":"主语 + 动词 ... + to do ...","meaning":"……以便做……","example":"The residents meet after dinner to discuss a quiet hour.","translation":"居民们晚餐后聚在一起，讨论安静时段的安排。","tip":"可改为 The residents meet after dinner so that they can discuss a quiet hour；保留同一执行者和目的关系。"}]}]};
